import { cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { BulkActionBar } from "@/components/patterns/bulk-action-bar";
import { DataTableFrame, TableCell, TableHeaderCell, TableRow, TableState } from "@/components/patterns/data-table-frame";
import { FilterBar, FilterField, FilterInput } from "@/components/patterns/filter-bar";
import { Pagination } from "@/components/patterns/pagination";
import { QuickFilterChips } from "@/components/patterns/quick-filter-chips";

afterEach(cleanup);

/** Chip name = label + count; the markup places them adjacent, so allow either spacing. */
const chip = (label: string, count: number) => new RegExp(`^${label}\\s?${count}$`);

describe("QuickFilterChips", () => {
  it("disables zero-count chips except the active one and reports the chosen value", () => {
    const onChange = vi.fn();
    render(
      <QuickFilterChips
        chips={[
          { count: 12, label: "Tất cả", value: "all" },
          { count: 0, label: "Bảo lưu", value: "reserved" },
          { count: 3, label: "Đang học", value: "active" },
          { count: 5, disabled: true, label: "Đã nghỉ", value: "withdrawn" },
        ]}
        label="Lọc nhanh theo trạng thái"
        onChange={onChange}
        value="all"
      />,
    );

    const group = screen.getByRole("group", { name: "Lọc nhanh theo trạng thái" });
    expect(within(group).getByRole("button", { name: chip("Tất cả", 12) })).toHaveAttribute("aria-pressed", "true");
    expect(within(group).getByRole("button", { name: chip("Bảo lưu", 0) })).toBeDisabled();
    expect(within(group).getByRole("button", { name: chip("Đã nghỉ", 5) })).toBeDisabled();

    fireEvent.click(within(group).getByRole("button", { name: chip("Bảo lưu", 0) }));
    expect(onChange).not.toHaveBeenCalled();
    fireEvent.click(within(group).getByRole("button", { name: chip("Đang học", 3) }));
    expect(onChange).toHaveBeenCalledWith("active");
  });

  it("keeps an active zero-count chip clickable so the user can leave an empty filter", () => {
    const onChange = vi.fn();
    render(
      <QuickFilterChips
        chips={[
          { count: 0, label: "Tất cả", value: "all" },
          { count: 0, label: "Bảo lưu", value: "reserved" },
        ]}
        label="Lọc nhanh"
        onChange={onChange}
        value="reserved"
      />,
    );

    const active = screen.getByRole("button", { name: chip("Bảo lưu", 0) });
    expect(active).toHaveAttribute("aria-pressed", "true");
    expect(active).toBeEnabled();
    expect(screen.getByRole("button", { name: chip("Tất cả", 0) })).toBeDisabled();
  });
});

describe("BulkActionBar", () => {
  it("renders only while something is selected and clears through Bỏ chọn", () => {
    const onClear = vi.fn();
    const { rerender } = render(
      <BulkActionBar onClear={onClear} selectedCount={0} subject="học sinh">
        <button type="button">Chuyển trạng thái…</button>
      </BulkActionBar>,
    );
    expect(screen.queryByRole("region")).not.toBeInTheDocument();

    rerender(
      <BulkActionBar onClear={onClear} selectedCount={3} subject="học sinh">
        <button type="button">Chuyển trạng thái…</button>
      </BulkActionBar>,
    );
    const bar = screen.getByRole("region", { name: "Đã chọn 3 học sinh" });
    expect(within(bar).getByRole("button", { name: "Chuyển trạng thái…" })).toBeInTheDocument();
    fireEvent.click(within(bar).getByRole("button", { name: "Bỏ chọn" }));
    expect(onClear).toHaveBeenCalledTimes(1);
  });

  // Value: protects=clearing a selection hands focus to the first focus target the current layout renders; fails_when=focus goes to a CSS-hidden control (desktop hides the mobile filter trigger) and drops to <body>; why_new=ship review pass C; seam=none; no_claim=does not prove which controls a real breakpoint hides (checkVisibility stubbed)
  it("returns focus to the first rendered candidate after Bỏ chọn", () => {
    const hidden = document.createElement("button");
    const visible = document.createElement("button");
    hidden.checkVisibility = () => false;
    visible.checkVisibility = () => true;
    document.body.append(hidden, visible);
    try {
      render(
        <BulkActionBar onClear={() => {}} returnFocusRefs={[{ current: hidden }, { current: visible }]} selectedCount={2} subject="học sinh" />,
      );
      fireEvent.click(screen.getByRole("button", { name: "Bỏ chọn" }));
      expect(document.activeElement).toBe(visible);
    } finally {
      hidden.remove();
      visible.remove();
    }
  });
});

describe("FilterBar", () => {
  it("shows Xóa lọc with the active count only when something is filtered", () => {
    const onReset = vi.fn();
    const fields = (
      <FilterField label="Tìm kiếm">
        <FilterInput onChange={() => {}} type="search" value="" />
      </FilterField>
    );
    const { rerender } = render(
      <FilterBar activeCount={0} label="Bộ lọc học sinh" onReset={onReset}>
        {fields}
      </FilterBar>,
    );
    expect(screen.getByRole("region", { name: "Bộ lọc học sinh" })).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /Xóa lọc/ })).not.toBeInTheDocument();

    rerender(
      <FilterBar activeCount={2} label="Bộ lọc học sinh" onReset={onReset}>
        {fields}
      </FilterBar>,
    );
    fireEvent.click(screen.getByRole("button", { name: "Xóa lọc (2)" }));
    expect(onReset).toHaveBeenCalledTimes(1);
  });
});

describe("DataTableFrame", () => {
  const header = (
    <tr>
      <TableHeaderCell>Học sinh</TableHeaderCell>
      <TableHeaderCell numeric>Số dư</TableHeaderCell>
    </tr>
  );
  const body = (
    <TableRow selected>
      <TableCell>Nguyễn A</TableCell>
      <TableCell numeric>3</TableCell>
    </TableRow>
  );

  it("renders rows only when ready and swaps in the matching state slot otherwise", () => {
    const { rerender } = render(
      <DataTableFrame body={body} caption="Danh sách" empty={<TableState>Không có dữ liệu</TableState>} error={<TableState>Lỗi tải</TableState>} footer={<span>1–1 trong 1</span>} header={header} />,
    );
    const table = screen.getByRole("table", { name: "Danh sách" });
    expect(within(table).getByRole("row", { selected: true })).toHaveTextContent("Nguyễn A");
    expect(within(table).getByRole("columnheader", { name: "Số dư" })).toHaveClass("text-right");
    expect(screen.getByText("1–1 trong 1")).toBeInTheDocument();
    expect(screen.queryByText("Không có dữ liệu")).not.toBeInTheDocument();

    rerender(
      <DataTableFrame body={body} caption="Danh sách" empty={<TableState>Không có dữ liệu</TableState>} error={<TableState>Lỗi tải</TableState>} header={header} status="empty" />,
    );
    expect(screen.queryByText("Nguyễn A")).not.toBeInTheDocument();
    expect(screen.getByText("Không có dữ liệu")).toBeInTheDocument();
    expect(screen.queryByText("Lỗi tải")).not.toBeInTheDocument();
    expect(screen.getByRole("columnheader", { name: "Học sinh" })).toBeInTheDocument();

    rerender(
      <DataTableFrame body={body} caption="Danh sách" empty={<TableState>Không có dữ liệu</TableState>} error={<TableState>Lỗi tải</TableState>} header={header} status="error" />,
    );
    expect(screen.getByText("Lỗi tải")).toBeInTheDocument();
    expect(screen.queryByText("Không có dữ liệu")).not.toBeInTheDocument();
  });
});

describe("Pagination", () => {
  const base = { itemLabel: "học sinh", label: "Phân trang học sinh", rangeEnd: 20, rangeStart: 1, total: 20 };

  it("keeps the frame summary on a single page but renders nothing standalone", () => {
    const onPageChange = vi.fn();
    const frame = render(<Pagination {...base} onPageChange={onPageChange} page={1} pageCount={1} summarySuffix="lọc theo lớp Toán 9A" variant="frame" />);
    expect(screen.getByText("1–20 trong 20 học sinh · lọc theo lớp Toán 9A")).toBeInTheDocument();
    expect(screen.queryByRole("navigation")).not.toBeInTheDocument();
    frame.unmount();

    const { container } = render(<Pagination {...base} onPageChange={onPageChange} page={1} pageCount={1} />);
    expect(container).toBeEmptyDOMElement();
  });

  it("windows page numbers around the current page and clamps prev/next at the edges", () => {
    const onPageChange = vi.fn();
    render(<Pagination {...base} onPageChange={onPageChange} page={5} pageCount={12} rangeEnd={100} rangeStart={81} total={240} />);

    const nav = screen.getByRole("navigation", { name: "Phân trang học sinh" });
    expect(within(nav).getAllByRole("button").map((button) => button.textContent)).toEqual(["Trước", "1", "4", "5", "6", "12", "Sau"]);
    expect(within(nav).getByRole("button", { name: "5" })).toHaveAttribute("aria-current", "page");
    fireEvent.click(within(nav).getByRole("button", { name: "Sau" }));
    expect(onPageChange).toHaveBeenCalledWith(6);

    cleanup();
    render(<Pagination {...base} onPageChange={onPageChange} page={12} pageCount={12} rangeEnd={240} rangeStart={221} total={240} />);
    expect(screen.getByRole("button", { name: "Sau" })).toBeDisabled();
    expect(screen.getByRole("button", { name: "Trước" })).toBeEnabled();
  });
});
